fn is_non_prime(n: u64) -> bool {
    // 2 and 3 are prime
    if n <= 3 {
        return false;
    }
    // handle even numbers > 2
    if n % 2 == 0 {
        return true;
    }
    // trial‐divide by odd k up to sqrt(n), checking k <= n/k to avoid overflow
    let mut k = 3;
    while k <= n / k {
        if n % k == 0 {
            return true;
        }
        k += 2;
    }
    false
}